56	  let timedOut = false;
57	  let aborted = false;
58	  let cleanupFailed = false;
59	  let processError: NodeJS.ErrnoException | null = null;
60	  let forceTimer: NodeJS.Timeout | undefined;
61	
62	  const terminate = () => {
63	    if (child.exitCode !== null || child.signalCode !== null) {
64	      return;
65	    }
66	    if (!child.kill('SIGTERM')) {
67	      cleanupFailed = true;
68	    }
